<style>
#salesTable{width:100%!important;min-width:1080px;border-collapse:collapse!important;color:#213b62;background:white}
#salesTable thead th{background:#edf6ff!important;color:#163760!important;text-transform:uppercase;font-weight:750!important;font-size:13px!important;padding:17px 20px!important;white-space:nowrap;border:1px solid #d7e5f5!important}
#salesTable tbody td{background:#fff!important;border:1px solid #dce7f4!important;padding:22px 20px!important;font-size:15px!important;line-height:1.5!important;color:#263c5d!important;vertical-align:middle!important;box-shadow:none!important}
#salesTable td:nth-child(2){min-width:200px}#salesTable td:nth-child(3){min-width:250px}#salesTable td:nth-child(4){min-width:180px}#salesTable td:nth-child(5){min-width:195px}#salesTable td:last-child{min-width:225px}
#salesTable .sale-invoice{display:inline-block;font-weight:750;color:#0068e8;font-size:17px;text-decoration:underline;margin-bottom:5px}
#salesTable .sale-detail{display:flex;align-items:center;gap:10px;margin:7px 0;color:#53647f}
#salesTable .sale-detail strong{color:#172e4c}
#salesTable .sale-detail i{color:#64748b}
#salesTable .sale-org{color:#718096;margin-bottom:9px}
#salesTable .sale-owner{display:inline-flex;align-items:center;gap:9px;background:linear-gradient(#00b85f,#008b59);color:white;font-weight:700;font-size:13px;padding:7px 12px;border-radius:5px}
#salesTable .sale-status-stack{display:flex;flex-direction:column;align-items:flex-start;gap:12px}
#salesTable .sale-status-stack>span:first-child{background:#e5f7f6;border-radius:6px;padding:8px 12px;color:#1c5270;font-weight:700}
#salesTable .sale-status-stack>span:first-child .badge{background:transparent!important;border:0!important;color:#1c5270!important;padding:0!important}
#salesTable .badge{padding:9px 13px!important;border-radius:5px!important;font-size:13px!important;font-weight:700!important}
#salesTable .badge.bg-danger{background:#ffe9ed!important;color:#dc0034!important}
#salesTable .badge.bg-success{background:#e1f7eb!important;color:#00854b!important}
#salesTable .badge.bg-warning{background:#fff3d5!important;color:#946100!important}
#salesTable .sale-amount>div{display:flex;align-items:baseline;gap:12px;margin:5px 0;white-space:nowrap}
#salesTable .sale-amount span{min-width:45px;color:#718096}
#salesTable .sale-total{color:#0064df}#salesTable .sale-paid{color:#00884d}#salesTable .sale-due{color:#e60035}
#salesTable .btn{display:inline-flex;justify-content:center;align-items:center;border-radius:5px!important;min-width:40px;min-height:40px;margin:2px!important;padding:10px!important;color:#fff;font-size:15px}
#salesTable .btn-primary{background:#0075ed!important;border-color:#0075ed!important}#salesTable .btn-danger{background:#ed0033!important;border-color:#ed0033!important}
#salesTable .btn-secondary{background:#657389!important;border-color:#657389!important}#salesTable .btn-dark{background:#24384e!important;border-color:#24384e!important}
#salesTable_wrapper{max-width:100%}
@media(max-width:768px){#salesTable tbody td{padding:17px 14px!important}#salesTable thead th{padding:14px!important}}
